            aMenuItemNodePropValues[ OFFSET_MENUITEM_IMAGEIDENTIFIER ] >>= aMenuImageId;
            ReadAndAssociateImages( aStrValue, aMenuImageId );

            pMenuItem[ OFFSET_MENUITEM_URL              ].Value <<= aStrValue;
